exercises.starter:
const cliente = 'Joana';
const parcelaCentavos = 4590;
const parcelas = 3;
const juros = 5;

// calcule em centavos e mostre as quatro linhas aqui

exercises.solution:
const cliente = 'Joana';
const parcelaCentavos = 4590;
const parcelas = 3;
const juros = 5;

const somaCentavos = parcelaCentavos * parcelas;
const jurosCentavos = Math.round(somaCentavos * juros / 100);
const totalCentavos = somaCentavos + jurosCentavos;

console.log(`Cliente: ${cliente}`);
console.log(`${parcelas} parcelas de R$ ${(parcelaCentavos / 100).toFixed(2)}`);
console.log(`Juros (${juros}%): R$ ${(jurosCentavos / 100).toFixed(2)}`);
console.log(`Total: R$ ${(totalCentavos / 100).toFixed(2)}`);

